class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        // 从下标 i 往后选，凑出 remain 的所有组合
        function<vector<vector<int>>(int, int)> dfs = [&](int i, int remain) -> vector<vector<int>> {
            if (remain == 0) {
                return vector<vector<int>>(1);              // 一个空组合
            }
            if (i == (int)candidates.size() || remain < 0) {
                return {};
            }
            int c = candidates[i];
            vector<vector<int>> res;
            for (auto& rest : dfs(i, remain - c)) {         // 再选一次 c
                rest.insert(rest.begin(), c);
                res.push_back(rest);
            }
            for (auto& rest : dfs(i + 1, remain)) {         // 以后都不选 c
                res.push_back(rest);
            }
            return res;
        };
        return dfs(0, target);
    }
};

